use vstd::prelude::*;

verus! {

fn concat(a: &[i32], b: &[i32]) -> (result: Vec<i32>)
    ensures
        result@ == a@ + b@,
{
    let mut result = Vec::new();
    
    // Copy all elements from a
    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            result.len() == i,
            forall|k: int| 0 <= k < i ==> result[k] == a[k],
    {
        result.push(a[i]);
        i = i + 1;
    }
    
    // Copy all elements from b
    let mut j: usize = 0;
    while j < b.len()
        invariant
            j <= b.len(),
            result.len() == a.len() + j,
            forall|k: int| 0 <= k < a.len() ==> result[k] == a[k],
            forall|k: int| 0 <= k < j ==> result[a.len() + k] == b[k],
    {
        result.push(b[j]);
        j = j + 1;
    }
    
    result
}

}

